// The "All" and "Unread" filter tabs.
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { chipTokens } from "ComponentTokens.stylex";
import UIPressable from "UIPressable.react";
import UIText from "UIText.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  tabs: { gap: 8, paddingInline: 8 },
  tab: { justifyContent: "center", paddingInline: 12, minHeight: 36, borderRadius: chipTokens.radius },
  selected: { backgroundColor: colors.accentAlpha20 },
});

export default function NotificationsTabs({ filter, onChange }) {
  return (
    <UIRow role="tablist" aria-label="Filter notifications" xstyle={styles.tabs}>
      {[
        ["all", "All"],
        ["unread", "Unread"],
      ].map(([key, label]) => (
        <UIPressable key={key} role="tab" aria-selected={filter === key} label={label} testid={`notifications-tab-${key}`} onPress={() => onChange(key)} xstyle={[styles.tab, filter === key && styles.selected]}>
          <UIText weight="semibold" color={filter === key ? "accent" : "secondary"}>
            {label}
          </UIText>
        </UIPressable>
      ))}
    </UIRow>
  );
}
