// The search field of the messenger menu (it doesn't filter the list).
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { searchInputTokens } from "ComponentTokens.stylex";
import UIIcon from "UIIcon.react";

const styles = stylex.create({
  field: { display: "flex", alignItems: "center", gap: 6, height: 36, paddingInline: 12, borderRadius: radii.pill, backgroundColor: colors.inputBackground, boxSizing: "border-box" },
  input: { border: 0, outline: "none", background: "none", fontSize: searchInputTokens.fontSize, color: colors.primaryText, width: "100%", minWidth: 0 },
});

export default function MessengerSearchField() {
  return (
    <label {...stylex.props(styles.field)}>
      <UIIcon name="search" size={16} />
      <input type="search" aria-label="Search Messenger" placeholder="Search Messenger" data-testid="messenger-search" {...stylex.props(styles.input)} />
    </label>
  );
}
