// One notification: the first actor's avatar with the kind badge, the body
// with its mentions as links, the time, the unread dot and the options menu.
import { useContext, useState } from "react";
import { graphql, useFragment } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { notificationItemTokens } from "ComponentTokens.stylex";
import UIText from "UIText.react";
import UIAvatar from "UIAvatar.react";
import UIPressable from "UIPressable.react";
import UIIconButton from "UIIconButton.react";
import { UIRow, UIColumn } from "UIStack.react";
import TextWithEntities from "TextWithEntities.react";
import NotificationKindBadge from "NotificationKindBadge.react";
import NotificationOptionsMenu from "NotificationOptionsMenu.react";
import { RouterContext } from "RouterContext";
import { shortRelativeTime } from "CurrentTime";

const styles = stylex.create({
  item: { position: "relative", gap: 4, paddingInline: 8, borderRadius: notificationItemTokens.radius },
  link: { flexGrow: 1, minWidth: 0 },
  content: { gap: notificationItemTokens.gap, paddingBlock: 8, minHeight: 72 },
  avatar: { position: "relative", flexShrink: 0 },
  dot: { width: 12, height: 12, borderRadius: "50%", backgroundColor: colors.accent, flexShrink: 0 },
});

export default function NotificationItem({ notification, unread, onToggleRead, onRemove, onNavigate }) {
  const data = useFragment(
    graphql`
      fragment NotificationItem_notification on Notification {
        id
        creation_time
        url
        icon_name
        body {
          ...TextWithEntities_text
        }
        actors {
          id
          name
          profile_picture(size: 56) {
            uri
          }
        }
        options {
          key
          label
          icon_name
        }
      }
    `,
    notification,
  );
  const router = useContext(RouterContext);
  const [menuOpen, setMenuOpen] = useState(false);
  const actor = data.actors?.[0];
  const options = (data.options ?? []).map((option) => (option.key === "read" ? { ...option, label: unread ? "Mark as read" : "Mark as unread" } : option));
  // Mentions in the body are links of their own and navigate by themselves;
  // only posts are routes of the app.
  const onOpen = (event) => {
    if (event?.target?.closest?.("a")) {
      return;
    }
    onNavigate();
    if (data.url?.startsWith("/posts/")) {
      router?.navigate(data.url);
    }
  };
  const onSelect = (key) => {
    setMenuOpen(false);
    if (key === "read") {
      onToggleRead(data.id);
    } else if (key === "remove") {
      onRemove(data.id);
    }
  };
  return (
    <UIRow role="listitem" data-testid="notification-item" xstyle={styles.item}>
      <UIPressable block role="link" logName="notification" onPress={onOpen} xstyle={styles.link}>
        <UIRow xstyle={styles.content}>
          <span {...stylex.props(styles.avatar)}>
            <UIAvatar src={actor?.profile_picture?.uri} size={56} />
            <NotificationKindBadge icon={data.icon_name} />
          </span>
          <UIColumn grow gap={2}>
            <UIText color={unread ? "primary" : "secondary"} weight={unread ? "medium" : null}>
              <TextWithEntities text={data.body} />
            </UIText>
            <UIText type="meta" color={unread ? "accent" : "secondary"} weight={unread ? "semibold" : null}>
              {shortRelativeTime(data.creation_time)}
            </UIText>
          </UIColumn>
          {unread ? <span aria-label="Unread" role="img" {...stylex.props(styles.dot)} /> : null}
        </UIRow>
      </UIPressable>
      <UIIconButton icon="more" label="Notification options" size={32} iconSize={16} filled={false} aria-expanded={menuOpen} onPress={() => setMenuOpen((open) => !open)} />
      {menuOpen ? <NotificationOptionsMenu options={options} onSelect={onSelect} /> : null}
    </UIRow>
  );
}
