// The account menu: the viewer's profile card, the settings menu's items
// and the footer links.
import { useEffect } from "react";
import { graphql, useLazyLoadQuery } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { emitStepEvent } from "Workload";
import UIMenu, { UIMenuItem } from "UIMenu.react";
import { UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import AccountProfileCard from "AccountProfileCard.react";
import AccountMenuFooter from "AccountMenuFooter.react";

const styles = stylex.create({
  panel: { padding: 8, gap: 8 },
});

export default function AccountMenuPanel({ onClose }) {
  const data = useLazyLoadQuery(
    graphql`
      query AccountMenuPanelQuery {
        viewer {
          actor {
            id
            name
            url
            profile_picture(size: 60) {
              uri
            }
          }
          settings_menu {
            items {
              key
              label
              icon_name
            }
          }
        }
      }
    `,
    {},
    { fetchPolicy: "store-or-network" },
  );
  useEffect(() => {
    emitStepEvent("menu-ready", { panel: "account" });
  }, []);
  const actor = data.viewer?.actor;
  const items = data.viewer?.settings_menu?.items ?? [];
  return (
    <LoggingSurface name="account_menu_panel">
      <UIColumn xstyle={styles.panel} data-testid="account-menu">
        {actor ? <AccountProfileCard actor={actor} onNavigate={onClose} /> : null}
        <UIMenu label="Account">
          {items.map((item) => (
            <UIMenuItem key={item.key} label={item.label} icon={item.icon_name} onPress={onClose} testid={`account-item-${item.key}`} />
          ))}
        </UIMenu>
        <AccountMenuFooter onNavigate={onClose} />
      </UIColumn>
    </LoggingSurface>
  );
}
