// A titled group of the apps menu's items.
import * as stylex from "@stylexjs/stylex";
import { menuItemTokens } from "ComponentTokens.stylex";
import UIText from "UIText.react";
import UIIcon from "UIIcon.react";
import UIPressable from "UIPressable.react";
import { UIColumn } from "UIStack.react";

const styles = stylex.create({
  title: { paddingInline: 8, paddingBlock: 4 },
  item: { alignItems: "flex-start", gap: menuItemTokens.gap, paddingInline: 8, paddingBlock: 8, borderRadius: menuItemTokens.radius },
  well: { display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, flexShrink: 0 },
});

export default function AppsMenuSection({ section, onPress }) {
  return (
    <UIColumn role="group" aria-label={section.title}>
      <UIText as="h3" type="body" color="secondary" weight="semibold" xstyle={styles.title}>
        {section.title}
      </UIText>
      {section.items.map((item) => (
        <UIPressable key={item.key} block label={item.label} testid={`apps-menu-${item.key}`} onPress={onPress} xstyle={styles.item}>
          <span {...stylex.props(styles.well)}>
            <UIIcon name={item.icon} size={28} color="accent" />
          </span>
          <UIColumn grow>
            <UIText weight="semibold">{item.label}</UIText>
            <UIText type="meta" color="secondary">
              {item.description}
            </UIText>
          </UIColumn>
        </UIPressable>
      ))}
    </UIColumn>
  );
}
