// One conversation in the messenger menu: avatar, name, the last message
// and its time, and the unread dot.
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { messengerItemTokens } from "ComponentTokens.stylex";
import UIText from "UIText.react";
import UIAvatar from "UIAvatar.react";
import UIPressable from "UIPressable.react";
import { UIRow, UIColumn } from "UIStack.react";
import { shortRelativeTime } from "CurrentTime";

const styles = stylex.create({
  row: { gap: messengerItemTokens.gap, paddingInline: 8, minHeight: 72, borderRadius: messengerItemTokens.radius },
  snippet: { gap: 4 },
  dot: { width: 12, height: 12, borderRadius: "50%", backgroundColor: colors.accent, flexShrink: 0 },
});

export default function MessengerThreadRow({ thread, onPress }) {
  const unread = thread.unread_count > 0;
  return (
    <UIPressable role="listitem" block label={thread.name} testid="messenger-thread" onPress={onPress} xstyle={styles.row}>
      <UIAvatar src={thread.image?.uri} size={56} />
      <UIColumn grow gap={2}>
        <UIText weight={unread ? "bold" : "medium"} numberOfLines={1}>
          {thread.name}
        </UIText>
        <UIRow xstyle={styles.snippet}>
          <UIText type="meta" color={unread ? "primary" : "secondary"} weight={unread ? "semibold" : null} numberOfLines={1}>
            {thread.snippet}
          </UIText>
          <UIText type="meta" color="secondary">
            {`· ${shortRelativeTime(thread.last_activity_time)}`}
          </UIText>
        </UIRow>
      </UIColumn>
      {unread ? <span aria-label="Unread" role="img" {...stylex.props(styles.dot)} /> : null}
    </UIPressable>
  );
}
