// The "Create" column of the apps menu.
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIIcon from "UIIcon.react";
import UIPressable from "UIPressable.react";
import { UIColumn } from "UIStack.react";
import { CREATE_ITEMS } from "AppsMenuItems";

const styles = stylex.create({
  column: { width: 200, flexShrink: 0, padding: 8, gap: 2, borderRadius: radii.lg, backgroundColor: colors.commentBackground, alignSelf: "flex-start" },
  title: { paddingInline: 8, paddingBlock: 4 },
  item: { gap: 12, paddingInline: 8, minHeight: 48, borderRadius: radii.md },
  well: { display: "flex", alignItems: "center", justifyContent: "center", width: 36, height: 36, borderRadius: "50%", backgroundColor: colors.secondaryButtonBackground, flexShrink: 0 },
});

export default function AppsMenuCreateColumn({ onPress }) {
  return (
    <UIColumn xstyle={styles.column} role="group" aria-label="Create">
      <UIText as="h3" type="headline3" xstyle={styles.title}>
        {fbt("Create", "heading of the create column of the apps menu")}
      </UIText>
      {CREATE_ITEMS.map((item) => (
        <UIPressable key={item.key} block label={item.label} testid={`apps-create-${item.key}`} onPress={onPress} xstyle={styles.item}>
          <span {...stylex.props(styles.well)}>
            <UIIcon name={item.icon} size={20} color="primary" />
          </span>
          <UIText weight="semibold">{item.label}</UIText>
        </UIPressable>
      ))}
    </UIColumn>
  );
}
