// The messenger menu: a heading with actions, a search field, the viewer's
// conversations and a link to all of them.
import { useEffect } from "react";
import { graphql, useLazyLoadQuery } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import { emitStepEvent } from "Workload";
import UIText from "UIText.react";
import UIIconButton from "UIIconButton.react";
import UIPressable from "UIPressable.react";
import UIDivider from "UIDivider.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import MessengerSearchField from "MessengerSearchField.react";
import MessengerThreadRow from "MessengerThreadRow.react";

const styles = stylex.create({
  panel: { padding: 8, gap: 8 },
  header: { paddingInline: 8, paddingTop: 4 },
  actions: { gap: 4 },
  footer: { justifyContent: "center", paddingBlock: 8 },
});

export default function MessengerPanel({ onClose }) {
  const data = useLazyLoadQuery(
    graphql`
      query MessengerPanelQuery {
        viewer {
          messenger_threads(first: 15) {
            edges {
              node {
                id
                name
                snippet
                last_activity_time
                unread_count
                image {
                  uri
                }
              }
            }
          }
        }
      }
    `,
    {},
    { fetchPolicy: "store-or-network" },
  );
  useEffect(() => {
    emitStepEvent("menu-ready", { panel: "messenger" });
  }, []);
  const threads = (data.viewer?.messenger_threads?.edges ?? []).map((edge) => edge.node).filter(Boolean);
  return (
    <LoggingSurface name="messenger_panel">
      <UIColumn xstyle={styles.panel} data-testid="messenger-list">
        <UIRow justify="between" xstyle={styles.header}>
          <UIText as="h2" type="headline2">
            {fbt("Chats", "heading of the messenger menu")}
          </UIText>
          <UIRow xstyle={styles.actions}>
            <UIIconButton icon="more" label="Options" size={36} filled={false} />
            <UIIconButton icon="expand" label="See all in Messenger" size={36} filled={false} />
            <UIIconButton icon="edit" label="New message" size={36} filled={false} />
          </UIRow>
        </UIRow>
        <MessengerSearchField />
        <UIColumn role="list" aria-label="Conversations">
          {threads.map((thread) => (
            <MessengerThreadRow key={thread.id} thread={thread} onPress={onClose} />
          ))}
        </UIColumn>
        <UIDivider />
        <UIRow xstyle={styles.footer}>
          <UIPressable as="a" href="/messages" logName="see-all-messenger" onPress={onClose}>
            <UIText type="body" color="link" weight="semibold">
              {fbt("See all in Messenger", "link at the bottom of the messenger menu")}
            </UIText>
          </UIPressable>
        </UIRow>
      </UIColumn>
    </LoggingSurface>
  );
}
