// The small menu behind a notification's "..." button.
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import UIMenu, { UIMenuItem } from "UIMenu.react";

const styles = stylex.create({
  menu: { position: "absolute", top: 44, right: 8, zIndex: 2, width: 260, borderRadius: radii.lg, backgroundColor: colors.popoverBackground, boxShadow: elevation.e4 },
});

export default function NotificationOptionsMenu({ options, onSelect }) {
  return (
    <div {...stylex.props(styles.menu)}>
      <UIMenu label="Notification options">
        {options.map((option) => (
          <UIMenuItem key={option.key} label={option.label} icon={option.icon_name} onPress={() => onSelect(option.key)} testid={`notification-option-${option.key}`} />
        ))}
      </UIMenu>
    </div>
  );
}
