// The small links at the bottom of the account menu.
import * as stylex from "@stylexjs/stylex";
import UIText from "UIText.react";
import UIPressable from "UIPressable.react";
import { UIRow } from "UIStack.react";

const styles = stylex.create({
  footer: { flexWrap: "wrap", gap: 4, paddingInline: 16, paddingBlock: 8 },
  link: { borderRadius: 2 },
});

const LINKS = ["Privacy", "Terms", "Advertising", "Ad choices", "Cookies", "More"];

export default function AccountMenuFooter({ onNavigate }) {
  return (
    <UIRow as="nav" aria-label="Legal" xstyle={styles.footer}>
      {LINKS.map((label, i) => (
        <UIRow key={label} gap={4}>
          <UIPressable as="a" href={`/${label.toLowerCase().replace(/ /g, "-")}`} logName={label} showOverlay={false} onPress={onNavigate} xstyle={styles.link}>
            <UIText type="caption" color="secondary">
              {label}
            </UIText>
          </UIPressable>
          {i < LINKS.length - 1 ? (
            <UIText type="caption" color="secondary" aria-hidden="true">
              {"·"}
            </UIText>
          ) : null}
        </UIRow>
      ))}
      <UIText type="caption" color="secondary">
        Circlet {"©"} 2026
      </UIText>
    </UIRow>
  );
}
