// The notifications menu: a heading, the All/Unread tabs and the viewer's
// notifications in a "New" and an "Earlier" section.
import { useEffect, useState } from "react";
import { graphql, useLazyLoadQuery } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import { emitStepEvent } from "Workload";
import UIText from "UIText.react";
import UIIconButton from "UIIconButton.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import NotificationsTabs from "NotificationsTabs.react";
import NotificationsSection from "NotificationsSection.react";

const styles = stylex.create({
  panel: { padding: 8, gap: 4 },
  header: { paddingInline: 8, paddingTop: 4 },
  empty: { padding: 24, textAlign: "center" },
});

export default function NotificationsPanel({ onClose }) {
  const data = useLazyLoadQuery(
    graphql`
      query NotificationsPanelQuery {
        viewer {
          notifications(first: 15) {
            edges {
              node {
                id
                seen_state
                ...NotificationItem_notification
              }
            }
          }
        }
      }
    `,
    {},
    { fetchPolicy: "store-or-network" },
  );
  const [filter, setFilter] = useState("all");
  const [overrides, setOverrides] = useState({});
  useEffect(() => {
    emitStepEvent("menu-ready", { panel: "notifications" });
  }, []);
  const update = (id, change) => setOverrides((current) => ({ ...current, [id]: { ...current[id], ...change } }));
  const onToggleRead = (id) => {
    const entry = entries.find((candidate) => candidate.node.id === id);
    update(id, { unread: !entry?.unread });
  };
  const onRemove = (id) => update(id, { removed: true });
  const entries = (data.viewer?.notifications?.edges ?? [])
    .map((edge) => edge.node)
    .filter((node) => node && !overrides[node.id]?.removed)
    .map((node) => ({ node, unread: overrides[node.id]?.unread ?? node.seen_state === "UNSEEN" }))
    .filter((entry) => filter === "all" || entry.unread);
  const fresh = entries.filter((entry) => entry.unread);
  const earlier = entries.filter((entry) => !entry.unread);
  return (
    <LoggingSurface name="notifications_panel">
      <UIColumn xstyle={styles.panel} data-testid="notifications-list">
        <UIRow justify="between" xstyle={styles.header}>
          <UIText as="h2" type="headline2">
            {fbt("Notifications", "heading of the notifications menu")}
          </UIText>
          <UIIconButton icon="more" label="Notification settings" size={36} filled={false} />
        </UIRow>
        <NotificationsTabs filter={filter} onChange={setFilter} />
        <NotificationsSection title={fbt("New", "section of unread notifications")} entries={fresh} onToggleRead={onToggleRead} onRemove={onRemove} onNavigate={onClose} />
        <NotificationsSection title={fbt("Earlier", "section of older notifications")} entries={earlier} onToggleRead={onToggleRead} onRemove={onRemove} onNavigate={onClose} />
        {entries.length === 0 ? (
          <UIText color="secondary" block xstyle={styles.empty}>
            {fbt("You have no notifications.", "empty state of the notifications menu")}
          </UIText>
        ) : null}
      </UIColumn>
    </LoggingSurface>
  );
}
