// The card at the top of the account menu: the viewer's avatar and name,
// linking to their profile.
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { accountMenuTokens } from "ComponentTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import fbt from "fbt";
import UIText from "UIText.react";
import UIAvatar from "UIAvatar.react";
import UILink from "UILink.react";
import UIButton from "UIButton.react";
import UIDivider from "UIDivider.react";
import { UIRow, UIColumn } from "UIStack.react";

const styles = stylex.create({
  card: { padding: 8, borderRadius: radii.lg, backgroundColor: colors.popoverBackground, boxShadow: elevation.e2, gap: 8 },
  profile: { gap: accountMenuTokens.gap, paddingInline: 8, minHeight: 60, borderRadius: accountMenuTokens.radius },
});

export default function AccountProfileCard({ actor, onNavigate }) {
  return (
    <UIColumn xstyle={styles.card} data-testid="account-profile-card">
      <UILink href={actor.url} block label={actor.name} onPress={onNavigate}>
        <UIRow xstyle={styles.profile}>
          <UIAvatar src={actor.profile_picture?.uri} size={44} />
          <UIText type="bodyLarge" weight="semibold" numberOfLines={1}>
            {actor.name}
          </UIText>
        </UIRow>
      </UILink>
      <UIDivider inset />
      <UIButton icon="friends" label={fbt("See all profiles", "button in the account menu")} />
    </UIColumn>
  );
}
