// The small round glyph on a notification's avatar that says what kind of
// notification it is.
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIIcon from "UIIcon.react";

const styles = stylex.create({
  badge: { position: "absolute", right: -4, bottom: -4, display: "flex", alignItems: "center", justifyContent: "center", width: 24, height: 24, borderRadius: "50%", backgroundColor: colors.accent, borderWidth: 2, borderStyle: "solid", borderColor: colors.popoverBackground, boxSizing: "border-box" },
});

export default function NotificationKindBadge({ icon }) {
  return (
    <span {...stylex.props(styles.badge)}>
      <UIIcon name={icon ?? "bell"} size={12} color="onAccent" filled={icon === "like" || icon === "comment"} />
    </span>
  );
}
