// The apps menu: a searchable list of the site's sections with their
// descriptions, next to the "Create" column. Static content, no query.
import { useEffect, useState } from "react";
import * as stylex from "@stylexjs/stylex";
import fbt from "fbt";
import { emitStepEvent } from "Workload";
import UIText from "UIText.react";
import { UIRow, UIColumn } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import AppsMenuSearchField from "AppsMenuSearchField.react";
import AppsMenuSection from "AppsMenuSection.react";
import AppsMenuCreateColumn from "AppsMenuCreateColumn.react";
import { APP_SECTIONS } from "AppsMenuItems";

const styles = stylex.create({
  panel: { alignItems: "flex-start", gap: 16, padding: 16 },
  main: { flexGrow: 1, gap: 8 },
  empty: { padding: 16 },
});

export default function AppsMenuPanel({ onClose }) {
  const [filter, setFilter] = useState("");
  useEffect(() => {
    emitStepEvent("menu-ready", { panel: "menu" });
  }, []);
  const needle = filter.trim().toLowerCase();
  const sections = APP_SECTIONS.map((section) => ({ ...section, items: section.items.filter((item) => !needle || item.label.toLowerCase().includes(needle)) })).filter((section) => section.items.length > 0);
  return (
    <LoggingSurface name="apps_menu_panel">
      <UIRow xstyle={styles.panel} data-testid="apps-menu">
        <UIColumn xstyle={styles.main}>
          <UIText as="h2" type="headline2">
            {fbt("Menu", "heading of the apps menu")}
          </UIText>
          <AppsMenuSearchField value={filter} onChange={setFilter} />
          {sections.map((section) => (
            <AppsMenuSection key={section.key} section={section} onPress={onClose} />
          ))}
          {sections.length === 0 ? (
            <UIText color="secondary" xstyle={styles.empty}>
              {fbt("No results found.", "empty state of the apps menu search")}
            </UIText>
          ) : null}
        </UIColumn>
        <AppsMenuCreateColumn onPress={onClose} />
      </UIRow>
    </LoggingSurface>
  );
}
