// A titled group of notifications ("New", "Earlier").
import * as stylex from "@stylexjs/stylex";
import UIText from "UIText.react";
import { UIColumn } from "UIStack.react";
import NotificationItem from "NotificationItem.react";

const styles = stylex.create({
  title: { paddingInline: 8, paddingBlock: 4 },
});

export default function NotificationsSection({ title, entries, onToggleRead, onRemove, onNavigate }) {
  if (entries.length === 0) {
    return null;
  }
  return (
    <UIColumn>
      <UIText as="h3" type="bodyLarge" weight="bold" xstyle={styles.title}>
        {title}
      </UIText>
      <UIColumn role="list">
        {entries.map(({ node, unread }) => (
          <NotificationItem key={node.id} notification={node} unread={unread} onToggleRead={onToggleRead} onRemove={onRemove} onNavigate={onNavigate} />
        ))}
      </UIColumn>
    </UIColumn>
  );
}
